insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-122', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'The $K_c$ expression for $2\mathrm{SO_2}(g) + \mathrm{O_2}(g) \rightleftharpoons 2\mathrm{SO_3}(g)$ is', '["$[\\mathrm{SO_3}]^2 / ([\\mathrm{SO_2}]^2[\\mathrm{O_2}])$","$[\\mathrm{SO_2}]^2[\\mathrm{O_2}] / [\\mathrm{SO_3}]^2$","$[\\mathrm{SO_3}] / [\\mathrm{SO_2}][\\mathrm{O_2}]$","$[\\mathrm{SO_3}]^2 / [\\mathrm{SO_2}][\\mathrm{O_2}]$"]'::jsonb, 0, 'Products over reactants with stoichiometric exponents: two for SO3, two for SO2, one for O2.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
