insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-123', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'Whenever $\Delta n = 0$ for a gas-phase equilibrium, $K_p$ and $K_c$ are', '["numerically equal","related by $RT$","related by $(RT)^2$","unrelated"]'::jsonb, 0, '$(RT)^{\Delta n} = 1$ when $\Delta n = 0$, so the two constants coincide numerically.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
