insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-125', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'At $300\ \mathrm{K}$, for a gas reaction with $\Delta n = +1$ and $R = 0.082\ \mathrm{L\ atm\ K^{-1}\ mol^{-1}}$, the ratio $K_p/K_c$ equals about', '["$24.6\\ \\mathrm{L\\ atm\\ mol^{-1}}$","$0.082$","$300$","$1$"]'::jsonb, 0, '$K_p/K_c = (RT)^{\Delta n} = RT = 0.082 \times 300 = 24.6$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
