insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-127', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'For $\mathrm{PCl_5} \rightleftharpoons \mathrm{PCl_3} + \mathrm{Cl_2}$, $K_c = 0.04\ \mathrm{mol\ L^{-1}}$. If $[\mathrm{PCl_3}] = [\mathrm{Cl_2}] = 0.20\ \mathrm{mol\ L^{-1}}$, the equilibrium $[\mathrm{PCl_5}]$ is', '["$1.0\\ \\mathrm{mol\\ L^{-1}}$","$0.04\\ \\mathrm{mol\\ L^{-1}}$","$0.20\\ \\mathrm{mol\\ L^{-1}}$","$0.008\\ \\mathrm{mol\\ L^{-1}}$"]'::jsonb, 0, '$K_c = [PCl3][Cl2]/[PCl5] = (0.20)(0.20)/[PCl5] = 0.04$, so $[PCl5] = 1.0\ \mathrm{mol\ L^{-1}}$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
