insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-130', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'For Haber synthesis $\Delta n = -2$, so at a given temperature $K_p$ is', '["smaller than $K_c$ by a factor $(RT)^2$","equal to $K_c$","larger than $K_c$ by $(RT)^2$","independent of $K_c$"]'::jsonb, 0, '$K_p = K_c(RT)^{-2} = K_c/(RT)^2$, hence $K_p < K_c$ at ordinary T where $RT > 1$ in L atm mol^{-1}.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
