insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-131', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'At $500\ \mathrm{K}$ with $R = 0.082\ \mathrm{L\ atm\ K^{-1}\ mol^{-1}}$, a gas reaction has $\Delta n = -1$. The ratio $K_c/K_p$ equals', '["$41$","$0.082$","$500$","$1$"]'::jsonb, 0, '$K_p = K_c/(RT)$, so $K_c/K_p = RT = 0.082 \times 500 = 41$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
