insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-132', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'The reaction $2\mathrm{SO_2} + \mathrm{O_2} \rightleftharpoons 2\mathrm{SO_3}$ has $K_c = 4$. For $\mathrm{SO_3} \rightleftharpoons \mathrm{SO_2} + \tfrac{1}{2}\mathrm{O_2}$, the new $K_c$ is', '["$0.50$","$4$","$2$","$0.25$"]'::jsonb, 0, 'Reversing gives $1/4$. Halving the equation takes the square root: $\sqrt{1/4} = 1/2$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
