insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source) values ('che-eq-134', 'chemistry-chemical-equilibrium-and-acids-bases', 'chemistry', 'Given $2\mathrm{NO}(g) + \mathrm{O_2}(g) \rightleftharpoons 2\mathrm{NO_2}(g)$ with $K_c = 100$, the constant for $\mathrm{NO_2}(g) \rightleftharpoons \mathrm{NO}(g) + \tfrac{1}{2}\mathrm{O_2}(g)$ is', '["$0.10$","$10$","$0.01$","$100$"]'::jsonb, 0, 'The target equation is the reverse of the original, halved. New $K = 1/\sqrt{100} = 0.10$.', '[]'::jsonb, '{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"}'::jsonb) on conflict (id) do update set stem = excluded.stem, options = excluded.options, answer_index = excluded.answer_index, explanation = excluded.explanation, images = excluded.images, source = excluded.source;
